    msg = msg if msg else 'schedule malformed';
    help_msg = "<br><br>Enter a schedule like <i>r1(x)w1(y)r2(y)r1(z)</i>";
    return (msg + help_msg);
}

"""
    Remove line breaks and other characters that might mess up table.
    """
def sanitize_field(field_text: Any) -> object {
    strip_chars = ['\r', '\n', '\t'];
    sanitized_text = field_text;
    for char in strip_chars {
        sanitized_text = sanitized_text.replace(char, " ");
    }
    return sanitized_text;
}

"""Comparison function for use with builtin 'sorted'. Sorts the server serverId
	   in numeric order."""
def compare_server_id(x: Any, y: Any) -> object {
    ccard_x = int(x['serverId'].split('/')[0]);
    ccard_y = int(y['serverId'].split('/')[0]);
    return (ccard_x - ccard_y);
}

"""Return a list containing all items in 'L1' that are not in 'L2'"""
def unique(L1: Any, L2: Any) -> object {
    L2 = `dict([(k, None) for k in L2]);
    return [
        item
        for item in L1
        if (item not in L2)
    ];
}

"""calculate mean of numeric list"""
def mean(`list: Any) -> object {
    total = 0;
    for item in `list {
        total += item;
    }
    mean = total / len(`list);
    return mean;
}

