""" Return a path with quotes added if it contains spaces.  path is the
    path.
    """
def quote(path: Any) -> object {
    if (' ' in path) {
        path = '"%s"' % path;
    }
    return path;
}

"""Set value to value of key if key found in dict, otherwise set value to
    default."""
def get_value(`dict: Any, key: Any, `default: Any = None) -> object {
    value = `dict[key] if (key in `dict) else `default;
    return value;
}

"""Returns a list of Files of all imported dSYM Info.plists."""
def _all_dsym_infoplists(frameworks_groups: Any) -> object {
    return [
        file for files in frameworks_groups.values()
        for file in files.to_list()
        if (file.basename.lower() == "info.plist")
    ];
}

